	/**
	 * Pre-scans the group's algebra for VALUES constants that cannot participate in raw-id execution and assigns each a
	 * plan-local synthetic id. Two cases qualify: terms with no id in the value store (they cannot match any stored
	 * statement, so probes bound to them are empty), and terms whose id is not raw-comparison-safe (inlined numerics)
	 * provided their variable never reaches a statement pattern or extension copy — for those the id is only ever
	 * materialized back to the original Value. Filters over synthetic variables are forced onto the generic
	 * (value-materializing) path.
	 */
	void collectSyntheticValues(TupleExpr expr) {
		HashSet<String> patternOrCopyVars = new HashSet<>();
		HashSet<String> computedExtensionVars = new HashSet<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				for (Var var : node.getVarList()) {
					// BindingSetAssignmentInlinerOptimizer can turn a named statement variable into a
					// valued Var while retaining its variable identity. It must still use the store's
					// raw term id: assigning the corresponding VALUES binding a synthetic id would make
					// the two occurrences incompatible even though they represent the same RDF term.
					if (var.getName() != null && !var.isAnonymous() && !var.isConstant()) {
						patternOrCopyVars.add(var.getName());
					}
				}
			}

			@Override
			public void meet(ExtensionElem node) {
				patternOrCopyVars.add(node.getName());
				if (node.getExpr() instanceof Var) {
					patternOrCopyVars.add(((Var) node.getExpr()).getName());
				} else {
					computedExtensionVars.addAll(VarNameCollector.process(node.getExpr()));
				}
				super.meet(node);
			}
		});
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(BindingSetAssignment node) {
				for (BindingSet bindings : node.getBindingSets()) {
					for (Binding binding : bindings) {
						Value value = binding.getValue();
						long id = idOf(value);
						boolean unknown = id == UNKNOWN;
						if ((unknown || !valueProbeSafeId(id, value))
								&& computedExtensionVars.contains(binding.getName())) {
							// Computed inline expressions decode through the physical LMDB codec. A
							// plan-local synthetic id is outside that codec's domain, so leave this
							// binding unallocated and make compileValues decline the native root.
							continue;
						}
						boolean unsafeEligible = !unknown && !valueProbeSafeId(id, value)
								&& !patternOrCopyVars.contains(binding.getName());
						if (unknown && !termSafeAbsenceProof(value)
								&& patternOrCopyVars.contains(binding.getName())) {
							// M-F1: a store-absent langString may exist under a term-equal spelling with its own
							// id, so a synthetic id must NOT constrain pattern probes — compileValues routes this
							// cell to the value-guarded fallback instead
							continue;
						}
						if (!unknown && !unsafeEligible) {
							continue;
						}
						planValueCatalog.internConstant(value);
						syntheticVarNames.add(binding.getName());
					}
				}
			}
		});
	}

	/**
	 * Whether a store miss for this value proves store absence: term-safe classes (IRIs, blank nodes, literals without
	 * a language tag) have exactly one possible store spelling. Language-tagged literals (and RDF-star triples, which
	 * can embed them) may exist under a different but term-equal spelling — mirrors
	 * {@link LmdbSyntheticValueSource#internEntryBinding}.
	 */
	static boolean termSafeAbsenceProof(Value value) {
		if (value instanceof Literal) {
			return ((Literal) value).getLanguage().isEmpty();
		}
		return value != null && (value.isIRI() || value.isBNode());
	}

	/**
	 * Whether compiling this root into one mutable slot row would let a descendant scope observe bindings that generic
	 * evaluation hides. The root itself may legitimately be a scope boundary when the generic evaluator compiles it as
	 * an isolated operand. Positive graph patterns remain safe under binding injection, so scope markers on UNION/MINUS
	 * branches do not by themselves disable their native operators; expressions are unsafe only when they can observe a
	 * hidden incoming name that their local operand does not assure.
	 */
	boolean containsUnsafeNestedVariableScopeChange(TupleExpr root) {
		return containsUnsafeScopeChange(root, Set.of(), Set.of(), false);
	}

	/**
	 * Whether an EXISTS witness needs per-solution domain-compatibility state that the current mutable-row filter does
	 * not carry. In particular, MINUS is not ordinary anti-existence: a right solution whose domain is disjoint from
	 * the current left solution removes nothing. Correlating such a nullable/shared right branch as a probe changes the
	 * result, so retain the scoped RDF4J evaluator unless every statically shared name is assured on both sides.
	 */
	boolean containsUnsafeExistsScope(TupleExpr root) {
		if (containsUnsafeNestedVariableScopeChange(root)) {
			return true;
		}
		if (root instanceof Difference difference) {
			Set<String> shared = sharedBindingNames(difference.getLeftArg(), difference.getRightArg());
			if (!difference.getLeftArg().getAssuredBindingNames().containsAll(shared)
					|| !difference.getRightArg().getAssuredBindingNames().containsAll(shared)) {
				return true;
			}
		}
		for (TupleExpr child : TupleExprs.getChildren(root)) {
			if (containsUnsafeExistsScope(child)) {
				return true;
			}
		}
		return false;
	}

	boolean containsVariableScopeChange(TupleExpr root) {
		if (TupleExprs.isVariableScopeChange(root)) {
			return true;
		}
		for (TupleExpr child : TupleExprs.getChildren(root)) {
			if (containsVariableScopeChange(child)) {
				return true;
			}
		}
		return false;
	}

